// השמעה חוזרת של הודעות קוליות מאביאל מתוך השיחה (26.10.26): רק קובץ שמופיע בשיחה של אותו מתאמן
function voiceById_(name, id) { if (!chatGet_(name).some(x => x.vid === id)) throw new Error('ההודעה הקולית לא נמצאה'); const f = DriveApp.getFileById(id);
  return { b64: Utilities.base64Encode(f.getBlob().getBytes()), mime: f.getMimeType() }; }
